/// This example prints the EmmyLua annotations auto-generated by the macro.
///
/// The output can be used by Lua LSP servers to provide autocompletion and
/// type-checking for your Lua config files.
use mlua::Lua;

#[brittle_lua::lua_module(crate = "brittle_lua")]
mod api {
    /// A top-level configuration.
    #[luaclass(name = "AppConfig")]
    #[derive(Clone)]
    pub struct AppConfig {
        /// The application name.
        pub name: String,
        /// The port to listen on.
        pub port: u16,
        /// Enable debug logging.
        pub debug: bool,
    }

    #[luamethods]
    impl AppConfig {
        /// Create a new config with defaults.
        pub fn new(name: String) -> mlua::Result<Self> {
            Ok(AppConfig {
                name,
                port: 3000,
                debug: false,
            })
        }

        /// Returns the listen address as a string.
        pub fn listen_addr(&self) -> String {
            format!("0.0.0.0:{}", self.port)
        }
    }
}

fn main() {
    let lua = Lua::new();
    api::register(&lua).expect("register");

    println!("=== 06_emmylua ===");
    println!("{}", api::EMMY_LUA);
}
